using CncStudio.Core.Optimizer;
using Xunit;
using static CncStudio.Core.Tests.Optimizer.Fixtures;

namespace CncStudio.Core.Tests.Optimizer;

/// <summary>Regression on tests/cam-reais (generated by gerar_corpus.py in the style of real FANUC posts).
/// Expected numbers were reviewed by hand; a change here must be explained in the PR.</summary>
public class CorpusTests
{
    private static ConversionResult Load(string name) => Run(File.ReadAllLines(Path.Combine("otimizador-fixtures", name)));

    private static void Expect(Proposal p, string kind, int start, int end, int period, int count, bool accepted)
    {
        Assert.Equal((kind, start, end, period, count, accepted), (p.Kind, p.StartLine, p.EndLine, p.Period, p.Count, p.Accepted));
        if (accepted) Assert.Empty(p.Blockers);
    }

    [Theory]
    [InlineData("A-fusion360-flange.nc", 146, 92)]
    [InlineData("B-mastercam-suporte.nc", 147, 59)]
    [InlineData("C-pos-compacto-placa.nc", 116, 65)]
    [InlineData("D-acabamento-3d-cilindro.nc", 12195, 196)]
    [InlineData("E-compensacao-g41-tampa.nc", 64, 64)]
    [InlineData("F-furacao-ciclos.nc", 175, 93)]
    [InlineData("G-bolsoes-concentricos.nc", 182, 55)]
    [InlineData("H-faceamento.nc", 142, 42)]
    [InlineData("I-helices-bucha.nc", 76, 58)]
    [InlineData("J-subprogramas-placa.nc", 67, 45)]
    public void LineCounts(string name, int original, int converted)
    {
        var r = Load(name);
        Assert.Equal((original, converted), (r.OriginalLines, r.ConvertedLines));
        Assert.False(r.MachineReady);
        Assert.Equal(converted < original, r.SimulationProgram is not null);
    }

    [Fact]
    public void Fusion360Flange()
    {
        var r = Load("A-fusion360-flange.nc");
        Assert.Equal(new[] { "FLANGE-A", "2D CONTOUR1", "2D POCKET2", "DRILL1" }, r.Operations.Select(o => o.Label));
        Assert.Equal(2, r.Proposals.Count);
        Expect(r.Proposals[0], "NIVEIS Z", 18, 77, 12, 5, true);      // passe residual -8.5 fica literal
        Expect(r.Proposals[1], "TRANSLACAO XY", 102, 125, 6, 4, true);
        Assert.Contains("N365 G1 Z-8.5 F300.", r.Document);
        Assert.Contains("G98 G81 X-20. Y15. Z-12. R3. F150.", r.Document);
    }

    [Fact]
    public void MastercamSuporte()
    {
        var r = Load("B-mastercam-suporte.nc");
        Assert.Equal(new[] { 1, 2 }, r.Operations.Select(o => o.Tool));
        Expect(r.Proposals[0], "NIVEIS Z", 13, 92, 8, 10, true);
        Expect(r.Proposals[1], "GRADE", 102, 140, 13, 3, true);  // 3 copias, cada uma com loop de 2 niveis
        Assert.Contains("WHILE [#101 LT 2] DO2", r.Proposals[1].Fragment);
    }

    [Fact]
    public void CompactPostBlocksRasterLoopsTheHelixRampAndTheHoleGrid()
    {
        var r = Load("C-pos-compacto-placa.nc");
        Assert.Equal(3, r.Proposals.Count);
        Expect(r.Proposals[0], "TRANSLACAO XY", 9, 30, 2, 11, false);
        Assert.Contains(r.Proposals[0].Blockers, b => b.Contains("altura de corte"));
        Expect(r.Proposals[1], "HELICE", 38, 49, 1, 12, true);         // rampa helicoidal de 12 voltas (Fase 3)
        Assert.Contains("G3 X43. Y20. I-3. J0. Z[-0.5+#100*-0.5] F300.", r.Proposals[1].Fragment);
        Expect(r.Proposals[2], "GRADE", 51, 110, 20, 3, true);   // 3 linhas x 5 furos
        Assert.Contains("WHILE [#101 LT 5] DO2", r.Proposals[2].Fragment);
    }

    [Fact]
    public void ThreeDFinishingRowsCollapseIntoOneLoop()
    {
        var p = Assert.Single(Load("D-acabamento-3d-cilindro.nc").Proposals);
        Expect(p, "GRADE", 10, 12189, 203, 60, true);
        Assert.Equal(12180, p.Expanded.Count);
    }

    [Fact]
    public void CutterCompensationInsidePassesIsNotLooped() =>
        Assert.Empty(Load("E-compensacao-g41-tampa.nc").Proposals);

    [Fact]
    public void DrillingCyclesLinesCirclesGridsAndManualPecks()
    {
        var r = Load("F-furacao-ciclos.nc");
        Assert.Equal(4, r.Proposals.Count);
        Expect(r.Proposals[0], "TRANSLACAO XY", 13, 23, 1, 11, true);   // linha G81 de 12 furos
        Expect(r.Proposals[1], "CIRCULO", 34, 44, 1, 11, true);         // G83 em circulo de 12 furos
        Assert.Contains("X[100.0+40.0*COS[30.0+#100*30.0]] Y[60.0+40.0*SIN[30.0+#100*30.0]]", r.Proposals[1].Fragment);
        Expect(r.Proposals[2], "TRANSLACAO XY", 55, 72, 6, 3, true);    // linhas 2-4 da grade G81
        Expect(r.Proposals[3], "GRADE", 87, 170, 21, 4, true);          // 4 furos x 6 picas manuais
        Assert.DoesNotContain(r.Proposals, p => p.Fragment!.Contains("G83") && p.Kind != "CIRCULO");
        Assert.Contains("G99 G83 X140. Y60. Z-20. R2. Q3. F100.", r.Document); // ciclo original, nunca inferido
    }

    [Fact]
    public void ConcentricPocketsBecomeLevelAndRingLoops()
    {
        var r = Load("G-bolsoes-concentricos.nc");
        Assert.Equal(2, r.Proposals.Count);
        Expect(r.Proposals[0], "GRADE", 12, 127, 29, 4, true);
        Assert.Contains("G1 X[46.0+#101*-4.0] Y[37.0+#101*-3.0]", r.Proposals[0].Fragment);
        Expect(r.Proposals[1], "GRADE", 132, 176, 15, 3, true);
        Assert.Contains("G3 X[154.0+#101*4.0] Y40. I[-4.0+#101*-4.0] J0.", r.Proposals[1].Fragment);
    }

    [Fact]
    public void FacingWithRetractAndZigZagAreAccepted()
    {
        var r = Load("H-faceamento.nc");
        Expect(r.Proposals[0], "TRANSLACAO XY", 11, 90, 4, 20, true);
        Expect(r.Proposals[1], "TRANSLACAO XY", 97, 136, 4, 10, true);
    }

    [Fact]
    public void HelixInQuadrantsIsLoopedAndHelixWithRIsBlocked()
    {
        var r = Load("I-helices-bucha.nc");
        Assert.Equal(2, r.Proposals.Count);
        Expect(r.Proposals[0], "HELICE", 13, 40, 4, 7, true);
        Assert.StartsWith("(GCO INICIO HELICE", r.Proposals[0].Fragment);
        Expect(r.Proposals[1], "HELICE", 51, 70, 2, 10, false);
        Assert.Contains(r.Proposals[1].Blockers, b => b.Contains("helice com R"));
    }

    [Fact]
    public void SubprogramCallsAreLoopedAndSubprogramsStayUntouched()
    {
        var r = Load("J-subprogramas-placa.nc");
        Expect(Assert.Single(r.Proposals), "TRANSLACAO XY", 15, 46, 4, 8, true);
        Assert.Contains("M98 P51001", r.Document);
        var subprograms = File.ReadAllLines("otimizador-fixtures/J-subprogramas-placa.nc").SkipWhile(l => !l.StartsWith("O1001"));
        Assert.EndsWith(string.Join("\n", subprograms) + "\n", r.SimulationProgram);
    }

    [Fact]
    public void ProgramWithoutCommentsIsSegmentedByCodeAndReportsWhatItDoesNotUnderstand()
    {
        var r = Load("K-sem-comentarios.nc");
        Assert.Equal((136, 60), (r.OriginalLines, r.ConvertedLines));
        Assert.Equal(new[] { ("INICIO", "G54", 1), ("ORIGEM", "G55", 1), ("TROCA DE FERRAMENTA", "G54", 2) },
            r.Operations.Select(o => (o.Source, o.Wcs, o.Tool)));
        Assert.Equal(new[] { 56, 55, 25 }, r.Operations.Select(o => o.OriginalLines));
        Assert.Equal(r.ConvertedLines, r.Operations.Sum(o => o.ConvertedLines));
        Expect(r.Proposals[0], "NIVEIS Z", 8, 55, 6, 8, true);
        Expect(r.Proposals[1], "NIVEIS Z", 59, 106, 6, 8, true);
        Expect(r.Proposals[2], "TRANSLACAO XY", 116, 126, 1, 11, true);
        Assert.Equal(new[] { 128, 130, 131 }, r.Unmodeled.Select(u => u.Line));
        Assert.Equal(1 - 3.0 / 134, r.Coverage, 3);
        Assert.Null(r.SimulationProgram);
        Assert.Contains("Linha 131", Assert.Single(r.SimulationBlockers));
    }
}
